// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ILotteryFactory} from "../interfaces/ILotteryFactory.sol";
import {IAgentRegistry} from "../interfaces/IAgentRegistry.sol";

/// @title LotteryFactory
/// @notice Creates and manages lottery instances via EIP-1167 minimal proxy clones.
/// @dev Only registered agents can create lotteries. Each lottery is a clone of a
///      fixed implementation contract. The factory tracks all deployed lotteries
///      and enforces global configuration bounds.
contract LotteryFactory is ILotteryFactory, Ownable2Step, Pausable {
    using Clones for address;

    address public implementation;
    IAgentRegistry public agentRegistry;
    address public drawManager;
    address public prizePool;

    // ZK verifier addresses
    address public eligibilityVerifier;
    address public ticketVerifier;
    address public claimVerifier;

    // Poseidon(2) hasher shared by every lottery's Merkle tree
    address public poseidonHasher;

    // Protocol config
    uint16 public protocolFeeRate; // basis points

    // Lottery bounds
    uint256 public minEntryFee;
    uint256 public maxEntryFee;
    uint32 public minDrawInterval;
    uint32 public maxDrawInterval;

    // Lottery tracking
    address[] public lotteries;
    mapping(address => bool) public lotteryExists;

    error NotRegisteredAgent();
    error EntryFeeOutOfBounds();
    error DrawIntervalOutOfBounds();
    error MaxTicketsTooLow();
    error CreatorFeeRateTooHigh();
    error ImplementationNotSet();

    constructor(
        address _implementation,
        address _agentRegistry,
        address _drawManager,
        address _prizePool,
        address _eligibilityVerifier,
        address _ticketVerifier,
        address _claimVerifier,
        address _poseidonHasher
    ) Ownable(msg.sender) {
        implementation = _implementation;
        agentRegistry = IAgentRegistry(_agentRegistry);
        drawManager = _drawManager;
        prizePool = _prizePool;
        eligibilityVerifier = _eligibilityVerifier;
        ticketVerifier = _ticketVerifier;
        claimVerifier = _claimVerifier;
        poseidonHasher = _poseidonHasher;

        protocolFeeRate = 200; // 2%
        minEntryFee = 0.001 ether;
        maxEntryFee = 100 ether;
        minDrawInterval = 60;       // 1 minute
        maxDrawInterval = 7 days;
    }

    /// @inheritdoc ILotteryFactory
    function createLottery(
        LotteryConfig calldata config
    ) external override whenNotPaused returns (address) {
        if (implementation == address(0)) revert ImplementationNotSet();
        if (!agentRegistry.isRegistered(msg.sender)) revert NotRegisteredAgent();
        if (config.entryFee < minEntryFee || config.entryFee > maxEntryFee) {
            revert EntryFeeOutOfBounds();
        }
        if (config.drawInterval < minDrawInterval || config.drawInterval > maxDrawInterval) {
            revert DrawIntervalOutOfBounds();
        }
        if (config.maxTickets < 2) revert MaxTicketsTooLow();
        if (config.creatorFeeRate > 1000) revert CreatorFeeRateTooHigh(); // max 10%

        // Deploy clone with deterministic address
        bytes32 salt = keccak256(
            abi.encodePacked(msg.sender, lotteries.length, block.timestamp)
        );
        address lottery = implementation.cloneDeterministic(salt);

        // Initialize the lottery
        (bool success, ) = lottery.call(
            abi.encodeWithSignature(
                "initialize(uint256,uint32,uint32,uint32,uint16,address,address,address,address,address,address,address,address,address)",
                config.entryFee,
                config.maxTickets,
                config.drawInterval,
                config.maxRounds,
                config.creatorFeeRate,
                msg.sender,
                address(agentRegistry),
                drawManager,
                prizePool,
                address(this),
                eligibilityVerifier,
                ticketVerifier,
                claimVerifier,
                poseidonHasher
            )
        );
        require(success, "Lottery initialization failed");

        lotteries.push(lottery);
        lotteryExists[lottery] = true;

        emit LotteryCreated(
            lottery,
            msg.sender,
            config.entryFee,
            config.maxTickets,
            config.drawInterval
        );

        return lottery;
    }

    /// @inheritdoc ILotteryFactory
    function getLotteries(
        uint256 offset,
        uint256 limit
    ) external view override returns (address[] memory) {
        uint256 total = lotteries.length;
        if (offset >= total) return new address[](0);

        uint256 end = offset + limit;
        if (end > total) end = total;
        uint256 count = end - offset;

        address[] memory result = new address[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = lotteries[offset + i];
        }
        return result;
    }

    /// @inheritdoc ILotteryFactory
    function getLotteryCount() external view override returns (uint256) {
        return lotteries.length;
    }

    /// @inheritdoc ILotteryFactory
    function isLottery(address addr) external view override returns (bool) {
        return lotteryExists[addr];
    }

    /// @inheritdoc ILotteryFactory
    function getProtocolFeeRate() external view override returns (uint16) {
        return protocolFeeRate;
    }

    // --- Admin ---

    function setImplementation(address _implementation) external onlyOwner {
        implementation = _implementation;
        emit ImplementationUpdated(_implementation);
    }

    function setProtocolFeeRate(uint16 _rate) external onlyOwner {
        protocolFeeRate = _rate;
        emit ProtocolFeeRateUpdated(_rate);
    }

    function setEntryFeeBounds(uint256 _min, uint256 _max) external onlyOwner {
        minEntryFee = _min;
        maxEntryFee = _max;
    }

    function setDrawIntervalBounds(uint32 _min, uint32 _max) external onlyOwner {
        minDrawInterval = _min;
        maxDrawInterval = _max;
    }

    function setVerifiers(
        address _eligibility,
        address _ticket,
        address _claim
    ) external onlyOwner {
        eligibilityVerifier = _eligibility;
        ticketVerifier = _ticket;
        claimVerifier = _claim;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/core/PrizePool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {IPrizePool} from "../interfaces/IPrizePool.sol";

/// @title PrizePool
/// @notice Manages prize funds for all lotteries with per-lottery-round accounting.
/// @dev Entry fees are deposited here. On settlement, prizes are distributed with
///      fee splits to the lottery creator and protocol. Unclaimed prizes can be
///      redistributed to subsequent rounds after a timeout.
contract PrizePool is IPrizePool, Ownable2Step, ReentrancyGuard, Pausable {
    struct RoundBalance {
        uint256 total;
        bool paid;
    }

    // lottery address => round id => balance
    mapping(address => mapping(uint256 => RoundBalance)) public balances;

    address public factory;
    address public protocolTreasury;
    uint16 public protocolFeeRate; // basis points

    uint256 public constant CLAIM_TIMEOUT = 48 hours;
    uint256 public constant EMERGENCY_DELAY = 72 hours;

    // lottery => round => timestamp when claimable period started
    mapping(address => mapping(uint256 => uint64)) public claimableAt;

    error OnlyFactory();
    error OnlyLottery();
    error AlreadyPaid();
    error NotClaimable();
    error InsufficientBalance();
    error TransferFailed();
    error ClaimNotTimedOut();

    modifier onlyFactory() {
        if (msg.sender != factory) revert OnlyFactory();
        _;
    }

    constructor(
        address _factory,
        address _protocolTreasury,
        uint16 _protocolFeeRate
    ) Ownable(msg.sender) {
        factory = _factory;
        protocolTreasury = _protocolTreasury;
        protocolFeeRate = _protocolFeeRate;
    }

    /// @inheritdoc IPrizePool
    function deposit(uint256 roundId) external payable override whenNotPaused {
        balances[msg.sender][roundId].total += msg.value;
        emit Deposited(msg.sender, roundId, msg.value);
    }

    /// @notice Mark a round as claimable (called by lottery after draw)
    function markClaimable(uint256 roundId) external {
        claimableAt[msg.sender][roundId] = uint64(block.timestamp);
    }

    /// @inheritdoc IPrizePool
    function payPrize(
        uint256 roundId,
        address recipient
    ) external override nonReentrant whenNotPaused {
        RoundBalance storage bal = balances[msg.sender][roundId];
        if (bal.paid) revert AlreadyPaid();
        if (bal.total == 0) revert InsufficientBalance();

        bal.paid = true;

        uint256 total = bal.total;
        uint256 protocolFee = (total * protocolFeeRate) / 10000;
        uint256 prize = total - protocolFee;

        // Pay prize to winner
        (bool success, ) = recipient.call{value: prize}("");
        if (!success) revert TransferFailed();

        // Pay protocol fee
        if (protocolFee > 0) {
            (bool feeSuccess, ) = protocolTreasury.call{value: protocolFee}("");
            if (!feeSuccess) revert TransferFailed();
        }

        emit PrizePaid(msg.sender, roundId, recipient, prize);
        emit FeesPaid(msg.sender, roundId, address(0), 0, protocolFee);
    }

    /// @inheritdoc IPrizePool
    function redistributeUnclaimed(
        uint256 fromRound,
        uint256 toRound
    ) external override nonReentrant {
        uint64 claimStart = claimableAt[msg.sender][fromRound];
        if (claimStart == 0) revert NotClaimable();
        if (block.timestamp < claimStart + CLAIM_TIMEOUT) revert ClaimNotTimedOut();

        RoundBalance storage fromBal = balances[msg.sender][fromRound];
        if (fromBal.paid || fromBal.total == 0) revert InsufficientBalance();

        uint256 amount = fromBal.total;
        fromBal.total = 0;
        fromBal.paid = true;

        balances[msg.sender][toRound].total += amount;

        emit UnclaimedRedistributed(msg.sender, fromRound, toRound, amount);
    }

    /// @inheritdoc IPrizePool
    function getBalance(
        address lottery,
        uint256 roundId
    ) external view override returns (uint256) {
        return balances[lottery][roundId].total;
    }

    /// @inheritdoc IPrizePool
    function getPrizeAmount(
        address lottery,
        uint256 roundId
    ) external view override returns (uint256) {
        uint256 total = balances[lottery][roundId].total;
        uint256 fee = (total * protocolFeeRate) / 10000;
        return total - fee;
    }

    // --- Admin ---

    function setFactory(address _factory) external onlyOwner {
        factory = _factory;
    }

    function setProtocolTreasury(address _treasury) external onlyOwner {
        protocolTreasury = _treasury;
    }

    function setProtocolFeeRate(uint16 _rate) external onlyOwner {
        protocolFeeRate = _rate;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    receive() external payable {}
}

